def add(name,protein,ingredients,steps,season='todas',minutes=35,country='',cost='medio',tip='',heat=0):
    vals={}
    for pair in ingredients.split():
        k,q=pair.split(':'); vals[k]=vals.get(k,0)+float(q)
    for k,q in [('ace',8),('sal',1),('pim',.2)]: vals.setdefault(k,q)
    R.append(dict(id=f'r{len(R)+1:03}',name=name,protein=protein,ingredients=[dict(name=I[k][0],unit=I[k][1],category=I[k][2],qty=q) for k,q in vals.items()],steps=steps.split('|'),seasons=season.split(','),minutes=minutes,country=country,cost=cost,tip=tip,heat=heat,base=1,difficulty='fácil' if minutes<=35 else 'media',prepMinutes=min(20,minutes//2),cookMinutes=minutes-min(20,minutes//2),freeze='Evaluar según los ingredientes; no congelar ensaladas frescas.',ahead='Se pueden preparar los ingredientes con anticipación, refrigerados.'))
